style.css:
@-moz-document domain("calendar.google.com") {
/* Google Calendar darker buttons */

:root {
  --button-dark: #2b2b2b;
  --button-hover: #3a3a3a;
  --button-active: #1f1f1f;
}

/* Primary buttons */
button[style*="background-color: rgb(26, 115, 232)"],
button.UywwFc-LgbsSe,
.UywwFc-LgbsSe {
  background-color: var(--button-dark) !important;
  border-color: var(--button-dark) !important;
  color: #ffffff !important;
}

/* Hover */
.UywwFc-LgbsSe:hover,
button:hover {
  background-color: var(--button-hover) !important;
}

/* Active */
.UywwFc-LgbsSe:active,
button:active {
  background-color: var(--button-active) !important;
}

/* Create button */
.TNczib {
  background-color: var(--button-dark) !important;
  color: white !important;
}

.TNczib:hover {
  background-color: var(--button-hover) !important;
}
}
